 function monta_grid($linhas = 0)
 {
   global $script_case_init, $nm_saida;
   $GLOBALS["script_case_init"] = $this->Ini->sc_page;

   clearstatcache();
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['SC_Ind_Groupby'] == "sc_free_total")
   { 
       if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['embutida'])
       { 
          include_once($this->Ini->path_embutida . "grid_itens_proc_compra/" . $this->Ini->Apl_resumo); 
       } 
       else 
       { 
          include_once($this->Ini->path_aplicacao . $this->Ini->Apl_resumo); 
       } 
       $this->Res         = new grid_itens_proc_compra_resumo();
       $this->Res->Db     = $this->Db;
       $this->Res->Erro   = $this->Erro;
       $this->Res->Ini    = $this->Ini;
       $this->Res->Lookup = $this->Lookup;
   } 
   $this->NM_cor_embutida();
   if (isset($_SESSION['scriptcase']['sc_apl_conf']['grid_itens_proc_compra']['field_display']) && !empty($_SESSION['scriptcase']['sc_apl_conf']['grid_itens_proc_compra']['field_display']))
   {
       foreach ($_SESSION['scriptcase']['sc_apl_conf']['grid_itens_proc_compra']['field_display'] as $NM_cada_field => $NM_cada_opc)
       {
           $this->NM_cmp_hidden[$NM_cada_field] = $NM_cada_opc;
       }
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['usr_cmp_sel']) && !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['usr_cmp_sel']))
   {
       foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['usr_cmp_sel'] as $NM_cada_field => $NM_cada_opc)
       {
           $this->NM_cmp_hidden[$NM_cada_field] = $NM_cada_opc;
       }
   }
   if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['php_cmp_sel']) && !empty($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['php_cmp_sel']))
   {
       foreach ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['php_cmp_sel'] as $NM_cada_field => $NM_cada_opc)
       {
           $this->NM_cmp_hidden[$NM_cada_field] = $NM_cada_opc;
       }
   }
   if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['grid_pesq'])) {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['grid_pesq'] = array();
   }
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['emb_apl_inex'] = array();
   if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['seq_iframe_emb'])) {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['seq_iframe_emb'] = 0;
   }
   if (!is_file($this->Ini->link_grid_anexos_proc_compra_item_amostra_cons_emb))
   {
       $this->NM_cmp_hidden['sb_doctos'] = "off";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['emb_apl_inex']['sb_doctos'] = true;
   }
   else
   {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_anexos_proc_compra_item_amostra']['embutida'] = true;
       $_SESSION['scriptcase']['grid_anexos_proc_compra_item_amostra']['protect_modal'] = $this->Ini->sc_page;
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_anexos_proc_compra_item_amostra']['exibe_titulos'] = "S";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_anexos_proc_compra_item_amostra']['exibe_total'] = "S";
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_anexos_proc_compra_item_amostra']['exibe_seq'] = "S";
       include_once ($this->Ini->link_grid_anexos_proc_compra_item_amostra_cons_emb);
       $this->grid_anexos_proc_compra_item_amostra = new grid_anexos_proc_compra_item_amostra_apl ;
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_anexos_proc_compra_item_amostra']['embutida'] = false;
       unset($_SESSION['scriptcase']['grid_anexos_proc_compra_item_amostra']['protect_modal']);
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['embutida_init'])
   { 
        return; 
   } 
   $this->inicializa();
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['charts_html'] = '';
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['embutida'])
   { 
       $this->Lin_impressas = 0;
       $this->Lin_final     = FALSE;
       $this->grid($linhas);
       $this->nm_fim_grid();
   } 
   else 
   { 
    if (strpos(" " . $this->Ini->SC_module_export, "grid") !== false) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['proc_pdf'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['proc_pdf_vert'])
            {
            } 
            else
            {
                $this->cabecalho();
            } 
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['proc_pdf'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['proc_pdf_vert'])
            {
            } 
            else
            {
       $nm_saida->saida("                  <TR>\r\n");
       $nm_saida->saida("                  <TD id='sc_grid_content' style='padding: 0px;' colspan=3>\r\n");
            } 
       $nm_saida->saida("    <table width='100%' cellspacing=0 cellpadding=0>\r\n");
       $nmgrp_apl_opcao= (isset($_SESSION['sc_session']['scriptcase']['embutida_form_pdf']['grid_itens_proc_compra'])) ? "pdf" : $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao'];
       if ($nmgrp_apl_opcao != "pdf")
       { 
           $this->nmgp_barra_top();
       } 
       unset ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['save_grid']);
       $this->grid();
       if ($nmgrp_apl_opcao != "pdf")
       { 
           $this->nmgp_barra_bot();
       } 
       $nm_saida->saida("   </table>\r\n");
       $nm_saida->saida("  </TD>\r\n");
       $nm_saida->saida(" </TR>\r\n");
    }
       if (strpos(" " . $this->Ini->SC_module_export, "resume") !== false)
       { 
           $Gera_res = true;
       } 
       else 
       { 
           $Gera_res = false;
       } 
       if (strpos(" " . $this->Ini->SC_module_export, "chart") !== false)
       { 
           $Gera_graf = true;
       } 
       else 
       { 
           $Gera_graf = false;
       } 
       if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['print_all'] && empty($this->nm_grid_sem_reg) && ($Gera_res || $Gera_graf) && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['SC_Ind_Groupby'] != "sc_free_total")
       { 
           $this->Res->monta_html_ini_pdf();
           $this->Res->monta_resumo();
           $this->Res->monta_html_fim_pdf();
           if ($Gera_graf)
           {
               $this->grafico_pdf();
           }
       } 
       $flag_apaga_pdf_log = TRUE;
       if (!$this->Print_All && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao'] == "pdf")
       { 
           $flag_apaga_pdf_log = FALSE;
       } 
       $this->nm_fim_grid($flag_apaga_pdf_log);
       if (!$this->Print_All && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao'] == "pdf")
       { 
           $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao'] = "igual";
       } 
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao_print'] == "print")
   {
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao'] = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao_ant'];
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao_print'] = "";
   }
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao_ant'] = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['opcao'];
 }
 function resume($linhas = 0)
 {
    $this->Lin_impressas = 0;
    $this->Lin_final     = FALSE;
    $this->grid($linhas);
 }
