    function scGetColumnOrderRule($fieldName)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['ordem_cmp'] == $fieldName) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['ordem_label'] == 'desc') {
                $sortRule = 'desc';
            } else {
                $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule, $skipUnusedClass = false)
    {
        $unusedClass = $skipUnusedClass ? '' : ' sc-grid-order-icon-unused';        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "item_proc_compra_id":
                return true;
            case "qt_dias_producao":
                return true;
            case "vl_custo_dolar":
                return true;
            case "vl_negociado":
                return true;
            case "qt_comprada":
                return true;
            case "tot_custo":
                return true;
            case "tot_custo_negoc":
                return true;
            case "qt_alocada":
                return true;
            case "qt_saldo":
                return true;
            case "vl_base_tributacao":
                return true;
            case "proc_compra_id":
                return true;
            case "cot_prevista":
                return true;
            case "vl_custo_final":
                return true;
            case "vl_rat_desp":
                return true;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "item_proc_compra_id":
                return 'desc';
            case "qt_dias_producao":
                return 'desc';
            case "vl_custo_dolar":
                return 'desc';
            case "qt_comprada":
                return 'desc';
            case "dt_item_certificacao":
                return 'desc';
            case "vl_base_tributacao":
                return 'desc';
            case "proc_compra_id":
                return 'desc';
        }
        return 'asc';
    }

