 function grid($linhas = 0)
 {
    global 
           $nm_saida;
   $fecha_tr               = "</tr>";
   $this->Ini->qual_linha  = "par";
   $HTTP_REFERER = (isset($_SERVER['HTTP_REFERER'])) ? $_SERVER['HTTP_REFERER'] : ""; 
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['rows_emb'] = 0;
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['embutida'])
   {
       if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['ini_cor_grid']) && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['ini_cor_grid'] == "impar")
       {
           $this->Ini->qual_linha = "impar";
           unset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['ini_cor_grid']);
       }
   }
   static $nm_seq_execucoes = 0; 
   static $nm_seq_titulos   = 0; 
   $this->SC_ancora = "";
   $this->Rows_span = 1;
   $nm_seq_execucoes++; 
   $nm_seq_titulos++; 
   $this->nm_prim_linha  = true; 
   $this->Ini->nm_cont_lin = 0; 
   $this->sc_where_orig    = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['where_orig'];
   $this->sc_where_atual   = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['where_pesq'];
   $this->sc_where_filtro  = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['where_pesq_filtro'];
// 
   $SC_Label = (isset($this->New_label['img_amostra_formato'])) ? $this->New_label['img_amostra_formato'] : "Formato Amostra";
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['labels']['img_amostra_formato'] = $SC_Label; 
   $SC_Label = (isset($this->New_label['cp_anexo'])) ? $this->New_label['cp_anexo'] : "Anexo";
   $_SESSION['sc_session'][$this->Ini->sc_page]['grid_itens_proc_compra']['labels']['cp_anexo'] = $SC_Label; 
