    if ($Cada_cmp == "sb_doctos" && (!isset($this->NM_cmp_hidden['sb_doctos']) || $this->NM_cmp_hidden['sb_doctos'] != "off"))
    {
       $colspan++;
    }
   }
   if ($colspan > 0)
   {
       $nm_saida->saida("     <TD class=\"" . $this->css_scGridTotalFont . "\"   " . "colspan=\"" . $colspan . "\"" . ">&nbsp;</TD>\r\n");
       $nm_saida->saida("    </TR>\r\n");
   }
 } 

