         $this->qt_comprada = $this->rs_grid->fields[7] ;  
         $this->qt_comprada = (string)$this->qt_comprada;  
         $this->dt_item_certificacao = $this->rs_grid->fields[8] ;  
         
/*----- Scriptcase Locale: Event onRecord ------*/
$_SESSION['scriptcase']['grid_itens_proc_compra']['contr_erro'] = 'on';
if (!isset($_SESSION['proc_compra_corrente'])) {$_SESSION['proc_compra_corrente'] = "";}
if (!isset($this->sc_temp_proc_compra_corrente)) {$this->sc_temp_proc_compra_corrente = (isset($_SESSION['proc_compra_corrente'])) ? $_SESSION['proc_compra_corrente'] : "";}
  $procCompraId = $this->sc_temp_proc_compra_corrente;
$this->tot_custo        = $this->qt_comprada   * $this->vl_custo_dolar ;
$this->tot_custo_negoc  = $this->qt_comprada   * $this->vl_negociado ;
$totDespesas   = $this->buscarTotDespesasProcCompra($procCompraId);
$totPond       = $this->buscarPonderacaoItensProcCompra($procCompraId);
if($totPond * $totDespesas <> 0){	
	$this->vl_rat_desp  =  $this->vl_custo_dolar  * $this->qt_comprada  / $totPond * $totDespesas;
}else{
	$this->vl_rat_desp  = 0;	
}	
$this->vl_custo_final  = $this->tot_custo  + $this->vl_rat_desp ;
$this->qt_alocada  =  $this->buscarQtAlocadaItemProcCompra($this->item_proc_compra_id );
$this->qt_saldo  = $this->qt_comprada  - $this->qt_alocada ;
if (isset($this->sc_temp_proc_compra_corrente)) {$_SESSION['proc_compra_corrente'] = $this->sc_temp_proc_compra_corrente;}
$_SESSION['scriptcase']['grid_itens_proc_compra']['contr_erro'] = 'off';
/*----- END - Scriptcase Locale: Event onRecord ------*/

         $this->tot_custo = (strpos(strtolower($this->tot_custo), "e")) ? (float)$this->tot_custo : $this->tot_custo; 
         $this->tot_custo = (string)$this->tot_custo;  
         $this->tot_custo_negoc = (strpos(strtolower($this->tot_custo_negoc), "e")) ? (float)$this->tot_custo_negoc : $this->tot_custo_negoc; 
         $this->tot_custo_negoc = (string)$this->tot_custo_negoc;  
