         $this->Res->adiciona_registro(NM_encode_input(sc_strip_script($this->qt_comprada)), NM_encode_input(sc_strip_script($this->tot_custo)), NM_encode_input(sc_strip_script($this->tot_custo_negoc)), NM_encode_input(sc_strip_script($this->qt_alocada)), NM_encode_input(sc_strip_script($this->qt_saldo)));
