function verificGrupoLogin($codGrupo)
{
$_SESSION['scriptcase']['grid_itens_proc_compra']['contr_erro'] = 'on';
  
    $log = false;
    $listaGrupos = $this->getGruposUsuario($this->getLoginCorrente());

    if($listaGrupos <> ''){
